entries[1243365] = { ["name"] = "Gegner-Hacking I", ["text"] = "Sofort\nErlangt Zugriff auf Konsolen in der Nähe von Loom'ithar und Seelenbinderin Naazindrhi, um alle Nicht-Boss-Gegner in deren Nähe deutlich zu schwächen." }
entries[1243366] = { ["name"] = "Gegner-Hacking II", ["text"] = "Sofort\nErweitert den Zugang zur arkanen Flusskontrolle bis zur Terrasse der Technomanten in der Nähe von Schmiedeweber Araz, damit Ihr normale Gegner in der Nähe deutlich schwächen könnt." }
entries[1243367] = { ["name"] = "Gegner-Hacking III", ["text"] = "Sofort\nÜbernehmt die direkte Kontrolle über alle Konsolen in der Manaschmiede. Dadurch erhaltet Ihr unbegrenzten wöchentlichen Zugriff und erhöht ihre Reichweite, damit auch Gegner in der Nähe von Nexuskönig Salhadaar und Dimensius betroffen sind." }
