entries[1243690] = { ["name"] = "Zerbrochener Raum", ["text"] = "1000 Meter Reichweite\nWirken in 3.25 sek.\nDimensius greift mit beiden Händen herab und reißt das Gefüge des Raums auf. Fügt Spielercharakteren innerhalb von 10 Metern der Reichweite jeder Hand 42161493 kosmischen Schaden zu und allen anderen Spielercharakteren 8783644 kosmischen Schaden.\n\nDieser gewaltige Akt erzeugt eine riesige Kugel aus Antimaterie an beiden Stellen und lässt einen Hagel aus Raumfragmenten um die Spielercharaktere herabgehen." }
