entries[1244387] = { ["name"] = "Resonantes Epochenandenken", ["text"] = "Wirken in 3 sek.\nFusioniert dieses Epochenandenken mit Eurer Artefaktwaffe, um eine Welle durch alle Zeitlinien und Versionen von \"Euch\" zu erzeugen.\n\nDieses mächtige Relikt steht in Resonanz mit Eurer Kriegsmeute und erhöht sämtliche erhaltene Erfahrung in Legion Remix dauerhaft um 1%." }
