entries[1244405] = { ["name"] = "Manageschmiedete Ätherzelle", ["text"] = "Ca. 2 Procs pro Minute\nEure Heilfähigkeiten haben eine Chance, die Ätherzelle mit Energie zu versorgen. Erhöht Eure Meisterschaft um 239 , pro Sekunde um ( 239 / 15) verringert. Hält 15 Sek. lang an." }
entries[1244406] = { ["name"] = "Symbiotische Äthergaze", ["text"] = "Ca. 2 Procs pro Minute\nBlocken, Parieren und Ausweichen haben eine Chance, die Gaze zu erwecken, sodass sie auf Gegner in der Nähe verteilt 1430 Arkanschaden zufügt und Euch einen Schild gewährt, der 8283 Schaden absorbiert und 15 Sek. lang anhält." }
