entries[1244414] = { ["name"] = "Unberechenbares Ritual", ["text"] = "Wirken in 3 sek.\nDer Zaubernde ruft K'aresh an, sodass ätherische Geister in erratischen Mustern nach außen wirbeln. Verursacht Arkanschaden und betäubt Gegner in ihrer Bahn." }
