entries[1245166] = { ["name"] = "Verweilender Teufelsblick", ["text"] = "100 Meter Reichweite\nSofort\nDer Starrer erschafft verweilende Augen, die zufällige Spielercharaktere mit Teufelsfeuer verbrennen und Spielercharakteren innerhalb von 6 Metern 6 Sek. lang alle 0.5 Sek. 1212225 Chaosschaden zufügen.\n\nBei Ablauf bleibt eine Teufelsfeuerlache zurück, die Spielercharakteren darin alle 1 Sek. 4848899 Chaosschaden zufügt." }
