entries[1245197] = { ["name"] = "Schauriges Streitross des kopflosen Reiters", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Fliegt durch die Lüfte, fahrt auf Eure Gegner herab, mit diesem Ross seid Ihr immer auf Zack.\"\nHandelsposten" }
entries[1245198] = { ["name"] = "Makabres Streitross des kopflosen Reiters", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Mit süßem Sieg über einen garstigen Reiter, ein ghulisches Ross für einen schaurigen Streiter.\"\nBeute von:\nBeutegefüllter Kürbis\nFeiertag:\nSchlotternächte" }
entries[1245202] = { ["name"] = "Brennendes Streitross des kopflosen Reiters", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"In Herz und Seele des Rosses ein Feuer erhellt, steigt in den Himmel und zeigt es der Welt.\"\nHandelsposten" }
entries[1245203] = { ["name"] = "Dunkles Massaker", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek.\nNetherphantome lauern Euch auf, schlagen aus den Schatten zu und verursachen 26140 Schattenschaden. Wenn Ihr ein sprintendes Phantom nicht anseht, verursacht es stattdessen 3485330 Schattenschaden." }
entries[1245205] = { ["name"] = "Geheiligtes Streitross des kopflosen Reiters", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Mit ungewisser Zukunft dank vergangener Taten, wie lang könnt Ihr das mit Eurem Ross noch ertragen?\"\nHandelsposten" }
