entries[1245289] = { ["name"] = "Verschlingen", ["text"] = "Sofort\nSobald er 100 Energie erreicht, erhöht Dimensius seine Dichte und erschafft eine mächtige, nach innen gerichtete Kraft, die 5 Sek. lang alle 1 Sek. 1686460 Schattenschaden verursacht und Spielercharaktere, Leerensterne, Schwarze Löcher und die Akkretionsscheibe hineinzieht.\n\nNach 5 Sek. wird jeder Spielercharakter außerhalb von ' Gravitationsbrunnen ' eines Leerensterns sofort in Dimensius hineingesogen und fällt ins ' Auslöschung '." }
