entries[1245292] = { ["name"] = "Destabilisiert", ["text"] = "Sofort\nDimensius ist erschüttert von Xal'ataths verheerendem Konterangriff. Erhöht sämtlichen erlittenen Schaden um 100%, bis er sich erholt." }
