entries[1245309] = { ["name"] = "Fokussierter Strahl", ["text"] = "100 Meter Reichweite\nWirken in 2.5 sek.\nDer Starrer entfesselt einen zerstörerischen Strahl, der einen zufälligen Spielercharakter verfolgt und Spielercharakteren innerhalb von 6 Metern alle 0.3 Sek. 1939560 Schattenschaden zufügt. Schaden und Geschwindigkeit des Strahls erhöhen sich alle 0.7 Sek. um 1%.\n\nWird der Strahl mithilfe einer Wächterlinse zum Starrer zurückgeworfen, wird ' Fokussierter Strahl ' unterbrochen und ein Teil von ' Fokus ' entfernt." }
entries[1245310] = { ["name"] = "Fokussierter Strahl", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nDer Starrer entfesselt einen zerstörerischen Strahl, der einen zufälligen Spielercharakter verfolgt und Spielercharakteren innerhalb von 6 Metern alle 0.3 Sek. 1939560 Schattenschaden zufügt. Schaden und Geschwindigkeit des Strahls erhöhen sich alle 0.7 Sek. um 1%.\n\nWird der Strahl mithilfe einer Wächterlinse zum Starrer zurückgeworfen, wird ' Fokussierter Strahl ' unterbrochen und ein Teil von ' Fokus ' entfernt." }
