entries[1245357] = { ["name"] = "Geschmückter Greif von Nordaeron", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Greifenreiterältesten und Hochschamanen der Wildhämmer von Nordaeron haben ihre Greifen oft mit kunstvollen, federbedeckten Teilen geziert, die ihren Rang und Status zur Schau stellten.\"\nHandelsposten" }
entries[1245358] = { ["name"] = "Fluggreif des Hochschamanen", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die antiken Schamanen der Wildhämmer, die den Greifen als erstes begegneten, glaubten, dass es sich bei ihnen um elementare Geister in sterblicher Form handelte. Diese Begegnung prägte den Wildhammerclan für alle kommenden Generationen.\"\nHandelsposten" }
entries[1245359] = { ["name"] = "Glutgefiederter Hochlandgreif", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Laut einer Legende der Wildhämmer soll das orangefarbene Gefieder der Greifen ein vererbtes Merkmal ihrer elementaren Vorfahren sein.\"\nHandelsposten" }
entries[1245360] = { ["name"] = "Geschoss" }
entries[1245361] = { ["name"] = "Himmelsführer der Glutschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Von den Gebirgsausläufern Khaz Modans sind wir seinen flammenden Schwingen gefolgt... eine Fackel die am dunklen Sommerhimmel gen Norden flog.\" - Die Pilgerfahrt des Ersten Wildweisen\nHandelsposten" }
entries[1245370] = { ["name"] = "Störrischer Brisenschreiter", ["text"] = "Wirken in 1.5 sek.\nStörrischen Brisenschreiter beschwören oder wieder freigeben.\n\"Dieses Talbuk ist ein stures, eigensinniges Reittier, selbst wenn es mit seinem Reiter vertraut ist. Mit Vorsicht zu genießen.\"\nHandelsposten" }
entries[1245376] = { ["name"] = "Arkanjäger", ["text"] = "Sofort\nEure kritischen Treffer mit schädlichen Zaubern und Distanzfähigkeiten haben eine hohe Chance, Euch bis zu 5-mal 'Arkanjäger' zu gewähren, was Euren kritischen Trefferwert 8 Sek. lang um 14 pro Stapel erhöht." }
entries[1245377] = { ["name"] = "Verlagerer platzieren", ["text"] = "Sofort\nSo'azmi setzt paarweise Verlagerer ein, um seine Gegner zu verwirren.\nBei Berührung eines Verlagerers werden Spielercharaktere sofort zum zugehörigen Verlagerer teleportiert." }
entries[1245382] = { ["name"] = "Aufgewühltes Wasser" }
entries[1245384] = { ["name"] = "Teufelsinferno", ["text"] = "Unbegrenzte Reichweite\nSofort\nVelaryn hüllt die Arena in Flammen und fügt allen Spielercharakteren mit jeder erschaffenen Flammensäule 843230 Feuerschaden sowie zusätzlich 15 Sek. lang alle 0.5 Sek. 182700 Feuerschaden zu. Dieser Effekt ist stapelbar.\n\nDie Flamme fügt allen Spielercharakteren, die in den Feuersturm treten, alle 1 Sek. 8435981 Feuerschaden zu." }
entries[1245385] = { ["name"] = "Berührung der Bosheit", ["text"] = "100 Meter Reichweite\nSofort\nEure Schaden verursachenden Zauber und Fähigkeiten sowie die Eurer Diener belegen Gegner regelmäßig mit ' Teufelsberührt '. Der durch ' Verdrehter Kreuzzug ' beschworene höllische Schreckenslord trifft mit ' Teufelsberührt ' belegte Gegner immer kritisch.\n\nTeufelsberührt\nAlle 4 Sek. explodiert das Ziel und fügt Gegnern in der Nähe 3% des in den letzten 4 Sek. erlittenen Schadens zu.\n(Procchance: 33%, 2s Abklingzeit)" }
