entries[1245397] = { ["name"] = "Manageschmiedete Ätherzelle", ["text"] = "Sofort\nEure Heilfähigkeiten haben eine Chance, die Ätherzelle mit Energie zu versorgen. Erhöht Eure Meisterschaft um 239 , pro Sekunde um ( 239 / 15) verringert. Hält 15 Sek. lang an." }
entries[1245416] = { ["name"] = "Hausfriedensbruch", ["text"] = "Sofort\nIhr befindet Euch ohne Erlaubnis auf dem Grundstück eines anderen Spielercharakters." }
entries[1245418] = { ["name"] = "Fokus" }
entries[1245422] = { ["name"] = "Arkaner Tsunami", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Seelenbinderin schlägt wütend auf ihr Primärziel ein und fügt diesem bis Abbruch lang alle 5.2 Sek. 0 Arkanschaden zu. Getroffene Spielercharaktere erleiden 45 Sek. lang um 40% erhöhten durch ' Mystische Peitsche ' Schaden und um 15% erhöhten körperlichen Schaden." }
