entries[1245430] = { ["name"] = "Arkane Infusion", ["text"] = "Sofort\nDer Zaubernde erfüllt alle Spielercharaktere innerhalb von 60 Metern mit arkaner Energie und fügt ihnen 4918841 Arkanschaden und zusätzlich 10 Sek. lang alle 1 Sek. 1194576 Arkanschaden zu.\n\nZusätzlich erhalten alle jungen Seidenraupen innerhalb von 60 Metern ' Arkane Bisse '." }
entries[1245431] = { ["name"] = "Symbiotische Äthergaze", ["text"] = "Sofort\nBlocken, Parieren und Ausweichen haben eine Chance, die Gaze zu erwecken, sodass sie auf Gegner in der Nähe verteilt 1430 Arkanschaden zufügt und Euch einen Schild gewährt, der 8283 Schaden absorbiert und 15 Sek. lang anhält." }
