entries[1245439] = { ["name"] = "Untersuchen", ["text"] = "Wirken in 5 sek.\nUntersucht das Simulaktrum und enthüllt seine wahre Natur." }
entries[1245440] = { ["name"] = "K'areshileerenstein", ["text"] = "Wirken in 2.5 sek.\nErfüllt Eure Rüstung mit einem schwachen Echo der Leere, was zusätzliche optische Effekte für bestimmte Klassensetvorlagen der Manaschmiede Omega, freischaltet.\n\nDieser Effekt gilt für die gesamte Kriegsmeute." }
