entries[1245529] = { ["name"] = "Zeichen der Ketten", ["text"] = "Unbegrenzte Reichweite\nSofort\nIlyssa platziert ein Zeichen der Ketten an der Position ihres aktuellen Ziels, das sich nach (5 / 2) Sek. aktiviert.\n\nAlle Spielercharaktere werden zu seinem Zentrum hingezogen und verlangsamt, was ihre Bewegungsgeschwindigkeit für 6 Sek. um 60% verringert." }
